ns.ACH_STEPS[62556] = {
    { t = "Go to this week's Ritual Site: Daggerspine Point in Eversong Woods or the Broken Throne in Zul'Aman (the map marks the active one). The Curious Obelisk there sets the tier and the challenges." },
    { t = "Choose Tier 5 with Tendrils and Manifestations. Going alone is easiest, and the Broken Throne is easier than Daggerspine Point (no water hiding the circles)." },
    { t = "Step out of every green circle at once, and pull enemies out of water and off stairs where the circles are hard to see." },
    { t = "Keep an interrupt or stun ready for every Manifestation (a Twilight Voidcaller) and use it on nothing else." },
    { t = "Kill the final boss. The achievement completes when the site does." },
}
ns.ACH_NOTES[62556] = { "Each player may be hit at most 3 times in total.", "Your pet being hit doesn't count.", "Tier 6 counts too.", "There's no counter; it's checked when the site ends." }
ns.ACH_SPOTS[62556] = { t = "Ritual Site (only this week's site is open)", at = { { 2395, 34.9, 65.4 }, { 2437, 29.7, 78.2 } } }
ns.ACH_REVIEWED[62556] = true

